    "mobileHtml": "<div class=\"diagram-mobile\" role=\"group\" aria-label=\"Log Investigation &amp; Verification\"><section class=\"mobile-stage\"><h3><span class=\"step-index\">01</span>Define the Issue</h3><section class=\"mobile-node action\"><p class=\"tag\">Observed Issue</p><h4>Capture the Time &amp; Object</h4><p>Error and timestamp</p><p>Identify camera, user or service</p></section><section class=\"mobile-node action\"><p class=\"tag\">Search Scope</p><h4>Filter the Log Records</h4><p>Use a relevant time range</p><p>Use supported filters and keywords</p></section><section class=\"mobile-node context\"><p class=\"tag\">Interpretation Context</p><h4>Check Coverage &amp; Access</h4><p>Deployment coverage</p><p>Keep related module evidence</p></section><p class=\"support-note\">The gray box lists supporting conditions for result verification.</p></section><section class=\"mobile-stage\"><h3><span class=\"step-index\">02</span>Collect Relevant Logs</h3><section class=\"mobile-node core\"><p class=\"tag\">Investigation Evidence</p><h4>Relevant Log Records</h4><p>Time-scoped log entries</p><p>Leads to verify in the module</p></section></section><section class=\"mobile-stage\"><h3><span class=\"step-index\">03</span>Validate &amp; Handoff</h3><section class=\"mobile-node action\"><p class=\"tag\">Correlation</p><h4>Follow the Event Sequence</h4><p>Read the event sequence</p><p>Link matching object references</p></section><section class=\"mobile-node action\"><p class=\"tag\">Module Verification</p><h4>Check the Affected Module</h4><p>Connection and settings</p><p>Verify the suspected cause</p></section><section class=\"mobile-node action\"><p class=\"tag\">Investigation Outcome</p><h4>Retest &amp; Document</h4><p>Retest after the change</p><p>Retain or export key evidence</p></section></section></div>",
